maxPages := datahelpers.GetIntField(config, "max_pages", 25)
rotate, _ := config["rotate_coverage"].(bool)

// rows now carry ord/name so the cursor and the ORDER BY cannot disagree
rows, err := params.DB.QueryContext(ctx, `
    SELECT COALESCE(url,''), COALESCE(nav_order,999) AS ord, name
    FROM pages WHERE site_id = $1::uuid
      AND `+datahelpers.PageWantedLivePredicateFor("")+`
      AND `+datahelpers.PageHasShippedPredicateFor("")+`
      AND COALESCE(url,'') <> ''
    ORDER BY COALESCE(nav_order,999), name`, siteID)

var window []auditPageRow
var next *auditCursor
var pri priorityResult
if rotate && total > maxPages {
    agentType := params.ExecutionContext.Sender.AgentType
    if agentType == "" {
        logger.Warn("rotate_coverage set but sender agent type is empty - falling back to prefix")
    } else {
        cur, _ := loadAuditCursor(ctx, params.DB, siteID, agentType)
        pri = selectPriorityPages(ctx, params.DB, siteID, all, cur, maxPages/2, logger)
        window, next = selectAuditWindow(all, cur, maxPages-len(pri.taken), pri.set)
        window = append(pri.taken, window...) // priority first: a truncated run measures them
    }
}
if window == nil {
    window = all[:min(len(all), maxPages)] // today's prefix, unchanged
}

// truncation row FIRST (it must outlive a failed dispatch), then produce,
// then the cursor (a commitment about the NEXT run must not outlive a failed send)
LogActionFindings(ctx, params, siteID, domain, "request_render_audit", []agenterrors.Finding{{
    ErrorCode: "RENDER_AUDIT_TRUNCATED", Severity: "warning",
    Message: truncationMessage(rotate, len(window), total, domain, next, pri),
    Context: truncationContext(rotate, window, total, maxPages, next, pri),
}}, logger)
if err := produce(...); err != nil { return nil, err }
if rotate && next != nil {
    if err := saveAuditCursor(ctx, params.DB, siteID, agentType, next); err != nil {
        logger.Warn("cursor write failed - this window will repeat next run",
            zap.String("window_first", next.Name), zap.Error(err))
    }
} else if rotate {
    deleteAuditCursor(ctx, params.DB, siteID, agentType) // cycle complete: restart at the top
}

// selectAuditWindow returns one contiguous slice past the cursor, plus the next cursor.
// Exact tuple match first, then first-strictly-greater, so a DELETED cursor page
// neither stalls the rotation nor restarts it from the top.
func selectAuditWindow(rows []auditPageRow, cur *auditCursor, n int, skip map[string]bool) ([]auditPageRow, *auditCursor) {
    start := 0
    if cur != nil {
        start = len(rows) // past-the-end unless we find a successor
        for i, r := range rows {
            if r.Ord == cur.Ord && r.Name == cur.Name { start = i + 1; break }
            if r.Ord > cur.Ord || (r.Ord == cur.Ord && r.Name > cur.Name) { start = i; break }
        }
        if start >= len(rows) { start = 0 } // cursor past the end: restart THIS run
    }
    out := make([]auditPageRow, 0, n)
    for i := start; i < len(rows) && len(out) < n; i++ {
        if skip[rows[i].URLPath] { continue } // already in the priority set: never send twice
        out = append(out, rows[i])
    }
    if len(out) == 0 { return rows[:min(len(rows), n)], nil } // never return empty: upstream reads it as no_deployed_pages
    if start+len(out) >= len(rows) { return out, nil }        // final window: caller clears the row
    last := out[len(out)-1]
    return out, &auditCursor{Ord: last.Ord, Name: last.Name}
}

// selectPriorityPages: the pages whose open findings THIS reply can grade.
// One item type by construction - write_render_audit_findings_action.go:791 calls
// loadAuditRetractionCandidates(..., "contrast_failure") and nothing else on this path.
func selectPriorityPages(ctx context.Context, db *sql.DB, siteID uuid.UUID,
    live []auditPageRow, cur *auditCursor, budget int, logger *zap.Logger) priorityResult {
    q := `SELECT item_key FROM site_work_items
           WHERE site_id = $1 AND item_type = 'contrast_failure'
             AND item_key LIKE 'contrast_failure:%'
             AND status NOT IN (` + sqlInList(workItemClosedStatuses) + `)`
    paths := map[string]bool{}
    for _, key := range queryKeys(ctx, db, q, siteID) {
        paths[pagePathFromContrastKey(key)] = true
    }
    var res priorityResult
    ordered := cyclicFrom(live, cur) // cyclic so an over-budget drop is not the same pages every run
    for _, r := range ordered {
        if !paths[r.URLPath] { continue }
        if len(res.taken) >= budget { res.dropped = append(res.dropped, r.URLPath); continue }
        res.taken = append(res.taken, r)
    }
    res.notLive = len(paths) - len(res.taken) - len(res.dropped)
    if len(res.dropped) > 0 {
        logger.Warn("priority regrade set exceeds its reserve - dropped this run; the drop rotates with the cursor, so no page is dropped permanently",
            zap.Int("budget", budget), zap.Strings("dropped", res.dropped))
    }
    return res
}

// pagePathFromContrastKey is the inverse of workItemKey("contrast_failure", path+"#"+sel).
// It lives beside the composer deliberately: a lockstep test round-trips through the
// real composer, so changing either spelling fails the build rather than silently
// emptying a join. Returns "" for a key that is not this shape.
func pagePathFromContrastKey(key string) string {
    const prefix = "contrast_failure:"
    if !strings.HasPrefix(key, prefix) { return "" }
    rest := strings.TrimPrefix(key, prefix)
    if i := strings.IndexByte(rest, '#'); i >= 0 { rest = rest[:i] }
    return rest
}

func TestSelectAuditWindow(t *testing.T) {
    rows := mkRows(200)
    cases := []struct{ name string; cur *auditCursor; n int; wantFirst string; wantNext bool }{
        {"no cursor takes the prefix", nil, 60, "p000", true},
        {"mid cycle starts at the successor", &auditCursor{100, "p059"}, 60, "p060", true},
        {"final window clears the cursor", &auditCursor{100, "p150"}, 60, "p151", false},
        {"deleted cursor page continues, never restarts", &auditCursor{100, "p059x"}, 60, "p060", true},
        {"cursor past the end restarts this run", &auditCursor{999, "zzz"}, 60, "p000", true},
    }
    for _, c := range cases { /* assert first element and next!=nil */ }
}

func TestPriorityPagesDoNotAdvanceTheCursor(t *testing.T) {
    // priority page at position 140; rotation window 61..120
    _, next := selectAuditWindow(rows, &auditCursor{100, "p060"}, 57, map[string]bool{"/p140": true})
    if next.Name != "p117" { t.Fatalf("cursor jumped to a priority page: %v", next) }
    // MUTATION: let priority pages set the cursor -> boundary becomes p140 and
    // p118..p139 appear in no window; the two-run coverage assertion below catches it.
}

func TestZeroPriorityKeysArePresentNotOmitted(t *testing.T) {
    ctx := truncationContext(true, window, 146, 60, next, priorityResult{})
    for _, k := range []string{"priority_paths", "priority_open_items", "priority_dropped", "priority_not_live"} {
        if _, ok := ctx[k]; !ok { t.Fatalf("%s omitted when zero - absence becomes ambiguous", k) }
    }
}

func TestPagePathFromContrastKeyRoundTrips(t *testing.T) {
    for _, p := range []string{"/index.html", "/tools/x.html"} {
        if got := pagePathFromContrastKey(workItemKey("contrast_failure", p+"#h1.hero")); got != p {
            t.Fatalf("round trip broke: %q -> %q", p, got)
        }
    }
}

BEGIN;
CREATE TABLE IF NOT EXISTS render_audit_page_cursor (
    site_id         uuid NOT NULL REFERENCES sites(id) ON DELETE CASCADE,
    agent_type      text NOT NULL,
    after_nav_order int  NOT NULL,
    after_name      text NOT NULL,
    updated_at      timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (site_id, agent_type)
);
COMMENT ON TABLE render_audit_page_cursor IS
  'bugs_open/394: keyset coverage cursor for request_render_audit (rotate_coverage callers only). '
  'Row present = mid-cycle; row absent = next capped run starts from the top. Written ONLY from Go. '
  'Safe to TRUNCATE: every cursor resets to the top, which is exactly pre-394 behaviour.';

UPDATE agent_definitions SET default_config = jsonb_set(
    default_config, '{workflow,steps,audit,config,rotate_coverage}', 'true'::jsonb, true)
WHERE type = 'render-audit-agent' AND is_active
  AND COALESCE(is_snapshot,false) = false AND deleted_at IS NULL;

DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM agent_definitions
   WHERE type='render-audit-agent' AND is_active AND COALESCE(is_snapshot,false)=false
     AND deleted_at IS NULL
     AND default_config#>>'{workflow,steps,audit,config,rotate_coverage}' = 'true';
  IF n <> 1 THEN
    RAISE EXCEPTION 'expected exactly 1 render-audit-agent row with rotate_coverage=true, got %', n;
  END IF;
END $$;
COMMIT;

BEGIN;
UPDATE agent_definitions
   SET default_config = default_config #- '{workflow,steps,audit,config,rotate_coverage}'
 WHERE type = 'render-audit-agent' AND is_active
   AND COALESCE(is_snapshot,false) = false AND deleted_at IS NULL;
DROP TABLE IF EXISTS render_audit_page_cursor;
COMMIT;

const renderTruncationCode = "RENDER_AUDIT_TRUNCATED"
const renderTruncationSink = "agent_error_log"

func checkRenderTruncation(ctx context.Context, db *sql.DB) (findings []string, err error) {
    rows, err := db.QueryContext(ctx, `
        SELECT domain, agent_type, occurred_at,
               COALESCE(context->>'coverage_mode',''), COALESCE(context->>'window_first','')
        FROM agent_error_log WHERE error_code = $1
        ORDER BY domain, agent_type, occurred_at DESC`, renderTruncationCode)
    // VACUITY GUARD (DBG-077): an empty table is an instrument failure, not a clean estate.
    if total == 0 {
        return nil, fmt.Errorf("refusing to report: no %s rows at all", renderTruncationCode)
    }
    for each (domain, agentType) group {
        if agentType == "render-audit-agent" && mode != "cursor" {
            findings = append(findings, "rotation caller wrote a prefix-mode row: the config flip regressed or the pod is on an old image")
        }
        if mode == "cursor" && windowFirst == prevWindowFirst {
            findings = append(findings, "cursor stalled: consecutive runs report the same window_first")
        }
        // design-critique-agent prefix rows are acked by design (manual sampler, no cadence)
    }
    return findings, nil
}
